SELECT id_elemento_html AS "IdElementoHtml", es_visible_menu AS "EsVisibleMenu", existe AS "Existe", id_usuario AS "IdUsuario", id_acceso AS "IdAcceso", nombre_acceso AS "NombreAcceso", tipo_acceso AS "TipoAcceso", padre AS "Padre", orden AS "Orden", id_servicio AS "IdServicio" FROM v_pla_acc_consultar_usuario_acceso WHERE id_empresa = :IdEmpresa AND id_usuario = :IdUsuario AND mostrar_acceso = 'S' ORDER BY padre NULLS FIRST, orden NULLS FIRST